class MiniGit:
    def __init__(self):
        self.commits = {}
        self.branches = {'main': None}
        self.head = 'main'
        self.next_id = 1

    def commit(self, msg):
        cid = 'c%d' % self.next_id
        self.next_id = self.next_id + 1
        self.commits[cid] = {'id': cid, 'parent': self.branches[self.head], 'msg': msg}
        self.branches[self.head] = cid
        return cid

    def log(self):
        lines = []
        node = self.branches[self.head]
        while node is not None:
            lines.append('%s %s' % (node, self.commits[node]['msg']))
            node = self.commits[node]['parent']
        return lines


